import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val n = reader.readLine().trim()
    val digits = n.map { it - '0' }
    val memo = Array(digits.size) { LongArray(1 shl 10) { -1L } }

    fun count(pos: Int, tight: Boolean, mask: Int): Long {
        if (Integer.bitCount(mask) > 2) return 0L
        if (pos == digits.size) return if (mask != 0) 1L else 0L

        if (!tight && memo[pos][mask] != -1L) {
            return memo[pos][mask]
        }

        val limit = if (tight) digits[pos] else 9
        var result = 0L

        for (digit in 0..limit) {
            val nextTight = tight && digit == limit
            val nextMask = if (mask == 0 && digit == 0) {
                0
            } else {
                mask or (1 shl digit)
            }

            if (Integer.bitCount(nextMask) <= 2) {
                result += count(pos + 1, nextTight, nextMask)
            }
        }

        if (!tight) memo[pos][mask] = result
        return result
    }

    print(count(0, true, 0))
}

