import java.io.BufferedReader
import java.io.InputStreamReader

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val digits = reader.readLine().trim().map { it - '0' }

    var dp = Array(2) { LongArray(1 shl 10) }
    dp[1][0] = 1L

    for (currentDigit in digits) {
        val next = Array(2) { LongArray(1 shl 10) }

        for (tight in 0..1) {
            val limit = if (tight == 1) currentDigit else 9

            for (mask in 0 until (1 shl 10)) {
                val count = dp[tight][mask]
                if (count == 0L) continue

                for (digit in 0..limit) {
                    val nextTight = if (tight == 1 && digit == limit) 1 else 0
                    val nextMask = if (mask == 0 && digit == 0) {
                        0
                    } else {
                        mask or (1 shl digit)
                    }

                    if (Integer.bitCount(nextMask) <= 2) {
                        next[nextTight][nextMask] += count
                    }
                }
            }
        }

        dp = next
    }

    var answer = 0L
    for (tight in 0..1) {
        for (mask in 1 until (1 shl 10)) {
            if (Integer.bitCount(mask) <= 2) {
                answer += dp[tight][mask]
            }
        }
    }

    print(answer)
}

